"""Context data loading helpers for the minijinja CLI replica."""
import configparser
import json
import os
import pathlib
from urllib.parse import parse_qs


EXT_FORMAT = {
    ".json": "json", ".json5": "json", ".toml": "toml",
    ".ini": "ini", ".conf": "ini", ".config": "ini", ".properties": "ini",
    ".qs": "querystring", ".yaml": "yaml", ".yml": "yaml", ".cbor": "cbor",
}


def parse_define(expr):
    """Parse one -D expression into (name, value), raising ValueError if invalid."""
    if ":=" in expr:
        key, raw = expr.split(":=", 1)
        try:
            value = json.loads(raw)
        except Exception as e:
            raise ValueError(f"invalid JSON value for definition {key!r}: {e}")
    elif "=" in expr:
        key, value = expr.split("=", 1)
    else:
        key, value = expr, True
    if not key:
        raise ValueError("definition name cannot be empty")
    return key, value


def parse_ini(text):
    # MiniJinja uses `default` for entries before the first named section.
    p = configparser.ConfigParser(interpolation=None, strict=False)
    p.optionxform = str
    try:
        # ConfigParser cannot preserve keys before a named section if any exist.
        if any(line.strip().startswith("[") for line in text.splitlines()):
            pre, post = [], []
            section_seen = False
            for line in text.splitlines():
                if line.strip().startswith("["): section_seen = True
                (post if section_seen else pre).append(line)
            source = (("[default]\n" + "\n".join(pre) + "\n") if any("=" in x for x in pre) else "") + "\n".join(post)
        else: source = "[default]\n" + text
        p.read_string(source)
    except configparser.Error as e:
        raise ValueError(str(e))
    result = {}
    for section in p.sections():
        result[section] = dict(p.items(section, raw=True))
    return result


def parse_toml(text):
    """Parse common TOML values using JSON scalar syntax and dotted sections."""
    out = {}
    current = out
    lines = text.splitlines()
    for idx, line in enumerate(lines):
        line = line.split("#", 1)[0].strip()
        if not line: continue
        if line.startswith("[") and line.endswith("]"):
            parts = line.strip("[]").split(".")
            current = out
            for part in parts: current = current.setdefault(part.strip(), {})
            continue
        if "=" not in line: raise ValueError("invalid TOML")
        key, raw = (x.strip() for x in line.split("=", 1))
        try: val = json.loads(raw)
        except Exception:
            if raw in ("true", "false"): val = raw == "true"
            elif raw.startswith("'") and raw.endswith("'"): val = raw[1:-1]
            elif raw.startswith("\"") and raw.endswith("\""): val = raw[1:-1]
            else:
                try: val = int(raw)
                except Exception:
                    try: val = float(raw)
                    except Exception: raise ValueError("invalid TOML value")
        current[key] = val
    return out


def parse_yaml(text):
    """Small standard-library YAML subset: mappings, sequences, and scalars."""
    # JSON is a valid YAML subset and is common for tests.
    try:
        return json.loads(text)
    except Exception:
        pass
    def scalar(s):
        s = s.strip()
        if s in ("", "null", "Null", "NULL", "~"): return None
        if s.lower() == "true": return True
        if s.lower() == "false": return False
        try: return json.loads(s)
        except Exception: return s.strip("\"'")
    root = {}
    stack = [(-1, root)]
    lines = text.splitlines()
    for idx, line in enumerate(lines):
        if not line.strip() or line.lstrip().startswith("#") or line.strip() in ("---", "..."): continue
        indent = len(line) - len(line.lstrip())
        body = line.strip()
        while len(stack) > 1 and indent <= stack[-1][0]: stack.pop()
        parent = stack[-1][1]
        if body.startswith("- "):
            if not isinstance(parent, list):
                raise ValueError("unsupported YAML sequence placement")
            parent.append(scalar(body[2:]))
        elif ":" in body:
            k, v = body.split(":", 1); k = str(scalar(k))
            if not v.strip():
                following = next((x for x in lines[idx + 1:] if x.strip()), "")
                child = [] if following.lstrip().startswith("- ") else {}
                parent[k] = child
                stack.append((indent, child))
            else: parent[k] = scalar(v)
        else: raise ValueError("unsupported YAML syntax")
    return root


def load_one(path, fmt="auto"):
    p = pathlib.Path(path)
    actual = EXT_FORMAT.get(p.suffix.lower()) if fmt == "auto" else fmt
    if not actual:
        raise ValueError(f"cannot detect input format for {path}")
    raw = p.read_bytes()
    if actual == "cbor":
        raise ValueError("CBOR format is not supported by this implementation")
    text = raw.decode("utf-8-sig")
    if actual == "json": return json.loads(text)
    if actual == "toml": return parse_toml(text)
    if actual == "ini": return parse_ini(text)
    if actual == "yaml": return parse_yaml(text)
    if actual == "querystring":
        return {k: (v[-1] if len(v) == 1 else v) for k, v in parse_qs(text, keep_blank_values=True).items()}
    raise ValueError(f"unsupported input format: {actual}")


