        opts = dict(cfg)
        opts["autoescape"] = esc
        opts["template_file"] = template_path
        opts["template_dir"] = os.path.dirname(os.path.abspath(template_path)) if args.template is None and template_path != "-" else os.getcwd()
        try: out = render(template, context, options=opts)
        except Exception as e:
            print("error:", e, file=sys.stderr); return 1
